#include <iostream>
#include <vector>
#include <algorithm>
#include <map>

using namespace std;

const long long MOD = 1000000007;

long long power(long long base, long long exp) {
    long long res = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp % 2 == 1) res = (__int128)res * base % MOD;
        base = (__int128)base * base % MOD;
        exp /= 2;
    }
    return res;
}

long long modInverse(long long n) {
    return power(n, MOD - 2);
}

struct Line {
    long long a, b;
};

struct Meal {
    long long a, b;
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    long long K_total;
    if (!(cin >> N >> M >> K_total)) return 0;

    vector<long long> a_spell(N), b_spell(N);
    for (int i = 0; i < N; ++i) cin >> a_spell[i];
    for (int i = 0; i < N; ++i) cin >> b_spell[i];

    vector<Meal> meals(M);
    for (int i = 0; i < M; ++i) cin >> meals[i].a;
    for (int i = 0; i < M; ++i) cin >> meals[i].b;

    // Sort meals optimally
    sort(meals.begin(), meals.end(), [](const Meal& u, const Meal& v) {
        __int128 left = (__int128)u.b * (v.a - 1);
        __int128 right = (__int128)v.b * (u.a - 1);
        return left > right;
    });

    long long A_ref = 1, B_ref = 0;
    for (int i = 0; i < M; ++i) {
        A_ref = (__int128)A_ref * meals[i].a % MOD;
        B_ref = ((__int128)B_ref * meals[i].a + meals[i].b) % MOD;
    }

    // Filter spells: for each distinct 'a', keep the maximum 'b'
    map<long long, long long> best_b;
    for (int i = 0; i < N; ++i) {
        if (best_b.find(a_spell[i]) == best_b.end()) {
            best_b[a_spell[i]] = b_spell[i];
        } else {
            best_b[a_spell[i]] = max(best_b[a_spell[i]], b_spell[i]);
        }
    }

    vector<Line> lines;
    for (auto const& [a, b] : best_b) {
        lines.push_back({a, b});
    }

    // Convex Hull Trick for Upper Envelope
    vector<Line> hull;
    auto intersect_ceil = [](const Line& l1, const Line& l2) -> long long {
        // Find smallest integer x such that l2(x) >= l1(x), where l2.a > l1.a
        if (l1.b <= l2.b) return 1;
        long long num = l1.b - l2.b;
        long long den = l2.a - l1.a;
        return (num + den - 1) / den;
    };

    for (const auto& l3 : lines) {
        while (hull.size() >= 1) {
            Line l2 = hull.back();
            if (hull.size() >= 2) {
                Line l1 = hull[hull.size() - 2];
                // Check if l2 is made redundant by l3
                // x_{23} <= x_{12}
                // (b2 - b3)/(a3 - a2) <= (b1 - b2)/(a2 - a1)
                __int128 left = (__int128)(l2.b - l3.b) * (l2.a - l1.a);
                __int128 right = (__int128)(l1.b - l2.b) * (l3.a - l2.a);
                if (left <= right) {
                    hull.pop_back();
                    continue;
                }
            }
            break;
        }
        hull.push_back(l3);
    }

    // Compute transition points X_k
    vector<long long> X(hull.size(), 1);
    for (size_t i = 1; i < hull.size(); ++i) {
        X[i] = intersect_ceil(hull[i - 1], hull[i]);
    }

    // Clean up lines that are dominated even for x >= 1
    vector<Line> final_hull;
    vector<long long> final_X;
    for (size_t i = 0; i < hull.size(); ++i) {
        while (!final_X.empty() && X[i] <= final_X.back()) {
            final_hull.pop_back();
            final_X.pop_back();
        }
        final_hull.push_back(hull[i]);
        final_X.push_back(final_hull.size() == 1 ? 1 : X[i]);
    }

    int Q;
    if (!(cin >> Q)) return 0;

    while (Q--) {
        long long x;
        cin >> x;
        long long K = K_total;

        while (K > 0) {
            // Find which line is active for current x
            // It's the last line with final_X[idx] <= x
            auto it = upper_bound(final_X.begin(), final_X.end(), x);
            int idx = (int)(it - final_X.begin()) - 1;

            if (idx == (int)final_hull.size() - 1) {
                // On the last line, all remaining K steps use this line
                Line l = final_hull[idx];
                if (l.a == 1) {
                    long long add = (__int128)(K % MOD) * (l.b % MOD) % MOD;
                    x = (x % MOD + add) % MOD;
                } else {
                    long long a_mod = l.a % MOD;
                    long long b_mod = l.b % MOD;
                    long long a_pow = power(a_mod, K);
                    long long geom_sum;
                    if ((a_mod - 1 + MOD) % MOD == 0) {
                        geom_sum = K % MOD;
                    } else {
                        geom_sum = (__int128)(a_pow - 1 + MOD) * modInverse((a_mod - 1 + MOD) % MOD) % MOD;
                    }
                    long long term1 = (__int128)(x % MOD) * a_pow % MOD;
                    long long term2 = (__int128)b_mod * geom_sum % MOD;
                    x = (term1 + term2) % MOD;
                }
                K = 0;
                break;
            } else {
                Line l = final_hull[idx];
                long long next_X = final_X[idx + 1];
                if (l.a == 1) {
                    long long diff = next_X - x;
                    long long steps = (diff + l.b - 1) / l.b;
                    long long take = min(K, steps);
                    x += take * l.b;
                    K -= take;
                } else {
                    x = l.a * x + l.b;
                    K--;
                }
            }
        }

        // Apply meals to x
        long long ans = ((__int128)A_ref * (x % MOD) + B_ref) % MOD;
        cout << ans << "\n";
    }

    return 0;
}
